const test = require('node:test');
const assert = require('node:assert/strict');
const {spawnSync} = require('node:child_process');
test('ordinary posture observations honor the disposable test clock', () => {
  const r = spawnSync('mix', ['run', '--no-start', '-e', 'Code.require_file("scrypath_ops/lib/scrypath_ops/posture.ex"); ExUnit.start(); Code.require_file("scrypath_ops/test/scrypath_ops/clock_test.exs")'], {
    cwd: '/Users/jon/projects/scrypath/.claude/worktrees/agent-p185-clock-lbu9p8_j',
    env: {...process.env,ASDF_ELIXIR_VERSION:'1.19.5-otp-28',ASDF_ERLANG_VERSION:'28.5',ERL_FLAGS:'+S 4',MIX_ENV:'test'},
    encoding:'utf8',timeout:120000,maxBuffer:4*1024*1024
  });
  assert.ifError(r.error);
  assert.equal(r.status,0,r.stdout+r.stderr);
});
